Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;

typedef bitset<128> u99;

constexpr const int mod = 1000000007;
constexpr const int inv =  570000004;
constexpr int add(int a, int b) { return a + b < mod ? a + b : a + b - mod; }
constexpr int sub(int a, int b) { return a < b ? a - b + mod : a - b; }
constexpr int mul(int a, int b) { return 1LL * a * b % mod; }

unordered_map<u99, int> name;
int n, dfn, son[65536][128];
int dfs(u99 s) {
	auto ite = name.find(s);
	if (ite != name.end()) return ite->second;
	int ret = dfn++;
	name[s] = ret;
	for (int i = 0; i != (1 << n); ++i) {
		u99 t = s;
		for (int j = 0; j != (1 << n); ++j) if (!t[j])
			for (int k = i & j; k; k ^= k & -k) if (s[j ^ k & -k]) {
				t[j] = 1;
				break;
			}
		son[ret][i] = dfs(t);
	}
	return ret;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
	cin >> n;
	dfs(1);
	for (int i = 0; i != n; ++i) for (int j = 0; j != n; ++j) cin >> p[i][j], p[i][j] = mul(p[i][j], inv);
	for (int i = 0; i != n; ++i) for (int j = 0; j != (1 << n); ++j) {
		q[i][j] = 1;
		for (int k = 0; k != n; ++k) q[i][j] = mul(q[i][j], j >> k & 1 ? p[k][i] : sub(1, p[k][i]));
	}
	dp[0][0] = 1;
	for (int i = 0; i != n; ++i) for (int j = 0; j != dfn; ++j) for (int k = 0; k != (1 << n); ++k)
		dp[i + 1][son[j][k]] = add(dp[i + 1][son[j][k]], mul(dp[i][j], q[i][k]));
	u99 res;
	for (int i = 0; i != (1 << n); ++i) res[i] = 1;
	cout << dp[n][name[res]] << endl;
}

</original_code>
